import time
import json
from storage import connect

class OutboxPublisher:
    def __init__(self, db):
        if db is None:
            raise ValueError("db connection must not be None")
        self.db = db

    def insert_event(self, agg_type, agg_id, payload, now=None):
        # Validate inputs
        if not isinstance(agg_type, str) or agg_type == "":
            raise ValueError("aggregate_type must be a non‑empty string")
        if not isinstance(agg_id, str) or agg_id == "":
            raise ValueError("aggregate_id must be a non‑empty string")
        # payload must be JSON serialisable
        try:
            payload_json = json.dumps(payload)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"payload must be JSON serialisable: {exc}")
        if now is None:
            now = time.time()
        if isinstance(now, bool) or not isinstance(now, (int, float)):
            raise ValueError("now must be a numeric timestamp")
        # Insert record
        cur = self.db.execute(
            "INSERT INTO outbox (aggregate_type, aggregate_id, payload, status, created_at) VALUES (?, ?, ?, 'PENDING', ?)",
            (agg_type, agg_id, payload_json, now),
        )
        self.db.commit()
        return cur.lastrowid

    def poll_and_publish(self, broker, batch_size=10, max_attempts=3, now=None):
        # Validate inputs
        if not hasattr(broker, "publish") or not callable(getattr(broker, "publish")):
            raise ValueError("broker must have a callable publish method")
        if isinstance(batch_size, bool) or not isinstance(batch_size, int) or batch_size <= 0:
            raise ValueError("batch_size must be a positive integer")
        if isinstance(max_attempts, bool) or not isinstance(max_attempts, int) or max_attempts <= 0:
            raise ValueError("max_attempts must be a positive integer")
        if now is None:
            now = time.time()
        if isinstance(now, bool) or not isinstance(now, (int, float)):
            raise ValueError("now must be a numeric timestamp")

        rows = self.db.execute(
            "SELECT id, aggregate_type, aggregate_id, payload, attempts FROM outbox WHERE status='PENDING' ORDER BY id ASC LIMIT ?",
            (batch_size,),
        ).fetchall()

        published_count = 0
        for row in rows:
            rec_id, agg_type, agg_id, payload_str, attempts = row
            payload = json.loads(payload_str)
            try:
                # Begin atomic transaction for this record
                self.db.execute("BEGIN")
                # Attempt to publish to broker
                broker.publish(agg_type, payload)
                # On success, mark as PUBLISHED
                self.db.execute(
                    "UPDATE outbox SET status='PUBLISHED', published_at=?, attempts=attempts WHERE id=?",
                    (now, rec_id),
                )
                self.db.commit()
                published_count += 1
            except Exception as exc:
                # Roll back any partial changes and retain PENDING status
                self.db.rollback()
                # Increment attempts and possibly move to FAILED if limit reached
                new_attempts = attempts + 1
                if new_attempts >= max_attempts:
                    self.db.execute(
                        "UPDATE outbox SET status='FAILED', attempts=? WHERE id=?",
                        (new_attempts, rec_id),
                    )
                else:
                    self.db.execute(
                        "UPDATE outbox SET attempts=? WHERE id=?",
                        (new_attempts, rec_id),
                    )
                self.db.commit()
                # Continue processing remaining rows
                continue
        return published_count
